import java.util.Properties

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("org.jetbrains.kotlin.plugin.compose")
    id("org.jetbrains.kotlin.plugin.serialization")
}

// Release signing: keystore.properties is generated by scripts/create-keystore.ps1 (not committed).
val keystorePropsFile = rootProject.file("keystore.properties")
val keystoreProps = Properties().apply {
    if (keystorePropsFile.exists()) {
        keystorePropsFile.inputStream().use { load(it) }
    }
}
val hasReleaseKeystore = keystoreProps.getProperty("storeFile") != null

// compatMode: 仅用于旧版模拟器（如 Android 7 x86_64）调试，降低 minSdk 并加入 x86_64。
//   powershell ... build-android.ps1 -Tasks assembleCompatDebug -Compat
// 正式包（assembleRelease）不要打开该开关。
val compatMode = (project.findProperty("compatMode") as String?)?.toBoolean() ?: false

android {
    namespace = "com.javboss.android"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.javboss.android"
        minSdk = if (compatMode) 24 else 22
        targetSdk = 36
        versionCode = 95
        versionName = "0.33.0"
        ndk {
            // 电视盒子多为 32 位（armeabi-v7a），手机多为 64 位（arm64-v8a）；两个都打进去，同一个包两端可装
            abiFilters += if (compatMode) {
                listOf("arm64-v8a", "armeabi-v7a", "x86_64")
            } else {
                listOf("arm64-v8a", "armeabi-v7a")
            }
        }
    }

    signingConfigs {
        if (hasReleaseKeystore) {
            create("release") {
                storeFile = rootProject.file(keystoreProps.getProperty("storeFile"))
                storePassword = keystoreProps.getProperty("storePassword")
                keyAlias = keystoreProps.getProperty("keyAlias")
                keyPassword = keystoreProps.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
            isMinifyEnabled = false
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            if (hasReleaseKeystore) {
                signingConfig = signingConfigs.getByName("release")
            }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    // 16 KB page size 兼容（Android 15+ 要求；Android 16 强制）
    packaging {
        jniLibs {
            useLegacyPackaging = false
        }
        resources {
            excludes += setOf("/META-INF/{AL2.0,LGPL2.1}", "/META-INF/DEPENDENCIES")
        }
    }

    androidResources {
        generateLocaleConfig = false
    }

    lint {
        abortOnError = false
        checkReleaseBuilds = false
    }
}

